package com.naveenans.olabatteryalert;
import android.app.Notification; import android.os.Bundle; import android.service.notification.NotificationListenerService; import android.service.notification.StatusBarNotification;
public class OlaNotificationListener extends NotificationListenerService { @Override public void onNotificationPosted(StatusBarNotification s){String pkg=s.getPackageName()==null?"":s.getPackageName().toLowerCase(); if(!pkg.contains("ola"))return; Bundle e=s.getNotification().extras; String all=String.valueOf(e.getCharSequence(Notification.EXTRA_TITLE,""))+" "+String.valueOf(e.getCharSequence(Notification.EXTRA_TEXT,""))+" "+String.valueOf(e.getCharSequence(Notification.EXTRA_BIG_TEXT,"")); Integer p=BatteryParser.fromText(all); if(p!=null)AlertEngine.process(this,p,"Ola notification");} }
